import json
from pathlib import Path


def format_record(order_id, total):
    return json.dumps({"order_id": order_id, "total": total})


def write_record(record, audit_path):
    Path(audit_path).write_text(record, encoding="utf-8")

def charge(order, total):
    if order.get("decline"):
        raise ValueError("payment declined")
    return "paid"

def calculate_total(order):
    if not order["items"]:
        raise ValueError("empty order")
    total = sum(item["price"] * item["quantity"] for item in order["items"])
    if order.get("promotion") == "SAVE10":
        total = total * 90 / 100
    return total
